# Edge proxy for the JSON API. Mounted over /etc/nginx/nginx.conf in nginx:1.28-alpine.
user nginx;
worker_processes auto;

# /var/run is not writable on the read-only root filesystem
pid /tmp/nginx.pid;

error_log /dev/stderr warn;

events {
  worker_connections 1024;
}

http {
  server_tokens off;

  # No query string: it can carry tokens, and this log is shipped to stdout
  log_format api_json escape=json
    '{"time":"$time_iso8601","remote_addr":"$remote_addr","request_id":"$request_id",'
    '"method":"$request_method","path":"$uri","status":$status,'
    '"bytes_sent":$body_bytes_sent,"request_time":$request_time,'
    '"upstream_time":"$upstream_response_time"}';
  access_log /dev/stdout api_json;

  # Docker's embedded DNS. Resolving at request time keeps the proxy working when the api
  # container is recreated and gets a new IP, which a startup-time upstream would not survive.
  resolver 127.0.0.11 valid=10s ipv6=off;

  client_max_body_size 1m;
  client_header_timeout 10s;
  client_body_timeout 10s;
  send_timeout 30s;
  keepalive_timeout 30s;

  add_header X-Content-Type-Options nosniff always;
  add_header X-Request-ID $request_id always;

  server {
    listen 80 default_server;
    server_name _;

    # Container healthcheck only. Requests from outside the container get 403.
    location = /nginx-health {
      access_log off;
      allow 127.0.0.1;
      deny all;
      return 200 "ok\n";
    }

    location / {
      set $api_upstream http://api:5000;
      proxy_pass $api_upstream;

      proxy_http_version 1.1;
      proxy_set_header Connection "";

      proxy_set_header Host $host;
      proxy_set_header X-Request-ID $request_id;

      # nginx is the public edge, so it overwrites client-supplied forwarding headers rather than appending to them
      proxy_set_header X-Forwarded-For $remote_addr;
      proxy_set_header X-Forwarded-Proto $scheme;
      proxy_set_header X-Forwarded-Host $host;

      # Gunicorn's sync workers are killed after 30s (see Dockerfile), so nginx waits a little longer and clients see the app's own failure, not a proxy timeout
      proxy_connect_timeout 5s;
      proxy_send_timeout 60s;
      proxy_read_timeout 60s;

      # Proxy-generated errors get a JSON body. Upstream responses pass through unchanged
      # because proxy_intercept_errors is off (the default), so an app 503 keeps its body.
      error_page 502 503 504 = @upstream_unavailable;
    }

    location @upstream_unavailable {
      internal;
      default_type application/json;
      return 503 '{"error":"upstream_unavailable"}\n';
    }
  }
}

